using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Enchantments;
using MegaCrit.Sts2.Core.Models.Powers;
using MegaCrit.Sts2.Core.Runs;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    internal StateFingerprint TaskClosedExhaustKey(CombatPredictionSimulator simulator)
    {
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        return BuildStateKey(combat.GetPlayerTurnNumber(_player), simulator.State.GetCreature(_player.Creature),
            simulator.State.GetPlayerCombatState(_player), combat, simulator, simulator.ShuffleEventCount, new HashSet<uint>());
    }
}

internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskClosedExhaustContractAsync(CombatState live, Player player)
    {
        string variant = Environment.GetEnvironmentVariable("TASK_CLOSED_EXHAUST_CASE")
            ?? throw new InvalidOperationException("Explicit closed-exhaust order required.");
        if (variant is not ("backstab-first" or "hunt-first")) throw new InvalidOperationException(variant);
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (var power in live.Creatures.SelectMany(creature => creature.Powers).ToArray()) await PowerCmd.Remove(power);
        foreach (PotionModel? potion in player.PotionSlots.ToArray()) potion?.Discard();
        await ClearPlayerPilesAsync(player);
        foreach (Creature enemy in live.Enemies) await CreatureCmd.SetMaxAndCurrentHp(enemy, 300);
        foreach (string id in new[] { "NOXIOUS_FUMES", "MASTER_PLANNER", "FAN_OF_KNIVES", "BLADE_OF_INK" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand", UpgradeLevels = 1 });
        await InjectCardAsync(live, player, new() { CardId = "DEFEND_SILENT", Pile = "Draw", Count = 6 });
        string first = variant == "backstab-first" ? "BACKSTAB" : "THE_HUNT";
        string second = variant == "backstab-first" ? "THE_HUNT" : "BACKSTAB";
        await InjectCardAsync(live, player, new() { CardId = first, Pile = "Exhaust" });
        CardModel attached = (await InjectCardAsync(live, player, new() { CardId = "SHIV", Pile = "Exhaust" })).Single();
        CardCmd.Enchant<Inky>(attached, 1);
        await InjectCardAsync(live, player, new() { CardId = second, Pile = "Exhaust" });
        await InjectCardAsync(live, player, new() { CardId = "SHIV", Pile = "Exhaust" });
        SetEnergy(player, 20);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null);
        var names = SolverDisplayNames.Capture(live);
        var solver = new CombatBeamSolver(root, names, BattleDamageTracker.Observe(live), policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string Rng(CombatPredictionSimulator sim) => JsonSerializer.Serialize(new {
            sim.Rng.ShuffleState, sim.Rng.CombatCardGenerationState, sim.Rng.CombatPotionGenerationState,
            sim.Rng.CombatCardSelectionState, sim.Rng.CombatEnergyCostsState, sim.Rng.CombatTargetsState,
            sim.Rng.CombatOrbGenerationState, sim.Rng.MonsterAiState, sim.Rng.NicheState, sim.ShuffleEventCount });
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            ((SimulatedCombatState)sim.State.CombatState).GetPlayerTurnNumber(player), root.Forecast, root.StartTurnNumber).StateText;
        string Full(CombatPredictionSimulator sim) => State(sim) + "\nKEY=" + solver.TaskClosedExhaustKey(sim)
            + "\nHISTORY=" + CardContinuationContractHistoryText(sim) + "\nRNG=" + Rng(sim)
            + "\nFLAGS=" + JsonSerializer.Serialize(new { sim.TerminalStamp, sim.IsInProgress, sim.IsAboutToLose });
        static string Hash(string text) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));
        static void Equal(string a, string b, string label)
        { if (a != b) throw new InvalidOperationException(label + " differs\nEXPECTED\n" + a + "\nACTUAL\n" + b); }
        CombatPredictionSimulator Canonical(CombatPredictionSimulator source)
        {
            var clone = source.Fork(); var pile = clone.State.GetPlayerCombatState(player).ExhaustPile;
            var cards = pile.Cards.ToArray();
            var free = cards.Select((card, index) => (card, index)).Where(x => x.card.Preview.Enchantment == null
                && x.card.Preview.Affliction == null).OrderBy(x => x.card.Preview.GetType().FullName, StringComparer.Ordinal)
                .ThenBy(x => x.index).Select(x => x.card).ToArray();
            int cursor = 0;
            for (int i = 0; i < cards.Length; i++) if (cards[i].Preview.Enchantment == null && cards[i].Preview.Affliction == null)
                cards[i] = free[cursor++];
            pile.Clear(); foreach (var card in cards) pile.Add(card);
            return clone;
        }
        var reverse = parent.Fork(); var reversePile = reverse.State.GetPlayerCombatState(player).ExhaustPile;
        var reversed = reversePile.Cards.ToArray(); (reversed[0], reversed[2]) = (reversed[2], reversed[0]);
        reversePile.Clear(); foreach (var card in reversed) reversePile.Add(card);
        if (solver.TaskClosedExhaustKey(parent) == solver.TaskClosedExhaustKey(reverse))
            throw new InvalidOperationException("Raw key failed to distinguish exhaust order.");
        Equal(Full(Canonical(parent)), Full(Canonical(reverse)), "initial full projected state/history/RNG");
        string parentBefore = Full(parent), reverseBefore = Full(reverse), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var expected = parent.Fork(); var opposite = reverse.Fork();
        void Play(CombatPredictionSimulator sim, string id)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            var combat = (SimulatedCombatState)sim.State.CombatState; var deaths = new ForkableSet<uint>();
            var card = sim.State.GetPlayerCombatState(player).Hand.Cards.Single(card => card.Preview.Id.Entry == id);
            using (combat.BeginCardExecutionScope(deaths))
                if (!sim.ManualPlay(card, null, out _)) throw new InvalidOperationException("Not playable: " + id);
            if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat) || sim.HasPendingChoice)
                throw new InvalidOperationException("Unexpected pending boundary: " + id);
            sim.CheckWinCondition(combat.GetPlayerTurnNumber(player));
        }
        var checkpoints = new List<object>();
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(35));
        foreach (string id in new[] { "NOXIOUS_FUMES", "MASTER_PLANNER", "FAN_OF_KNIVES", "BLADE_OF_INK" })
        {
            Play(expected, id); Play(opposite, id);
            Equal(Full(Canonical(expected)), Full(Canonical(opposite)), id + " projected full continuation");
            Equal(parentBefore, Full(parent), "parent isolation"); Equal(reverseBefore, Full(reverse), "reversed parent isolation");
            if (checkpoints.Count == 0) Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "shadow/live isolation");
            CardModel native = player.PlayerCombatState!.Hand.Cards.Single(card => card.Id.Entry == id);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                action => action is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), native),
                () => { if (!native.TryManualPlay(null)) throw new InvalidOperationException("Native not playable: " + id); }, deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
            Equal(State(expected), ContinuationStamp.CaptureLive(live).StateText, id + " native full state");
            AssertSnapshotEqual(CaptureSimulated(expected, (SimulatedCombatState)expected.State.CombatState, player, root.Enemies[0]),
                CaptureActual(live, player, root.Enemies[0]), "CLOSED_EXHAUST", id);
            checkpoints.Add(new { id, normalizedFullSha256 = Hash(Full(Canonical(expected))), nativeSha256 = Hash(State(expected)),
                hand = expected.State.GetPlayerCombatState(player).Hand.Cards.Count });
        }
        string expectedBefore = Full(expected); string beforeForkLive = ContinuationStamp.CaptureLive(live).StateText;
        var children = Enumerable.Range(0, 16).Select(_ => expected.Fork()).ToArray();
        foreach (var child in children) Equal(expectedBefore, Full(child), "complete Fork");
        await Task.WhenAll(children.Select((child, index) => Task.Run(() => {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            var card = child.State.GetPlayerCombatState(player).Hand.Cards.First(card => card.Preview.Enchantment is Inky);
            card.MutablePreview.Enchantment!.Amount = index + 2;
        })));
        for (int i = 0; i < children.Length; i++)
        {
            var card = children[i].State.GetPlayerCombatState(player).Hand.Cards.First(card => card.Preview.Enchantment is Inky);
            if (card.Preview.Enchantment!.Amount != i + 2) throw new InvalidOperationException("Attached Fork leaked.");
            Equal(Rng(expected), Rng(children[i]), "Fork RNG isolation");
        }
        Equal(expectedBefore, Full(expected), "attached source isolation");
        Equal(beforeForkLive, ContinuationStamp.CaptureLive(live).StateText, "attached live isolation");
        CombatRootSnapshot endRoot = CombatRootSnapshot.Capture(live);
        var endSolver = new CombatBeamSolver(endRoot, SolverDisplayNames.Capture(live), BattleDamageTracker.Observe(live), policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        SimulationSnapshot ended;
        using (SimulationNotificationIsolation.Enter()) ended = endSolver.ReplayEndTurnForTesting();
        int previous = player.PlayerCombatState!.TurnNumber;
        CombatManager.Instance.OnEndedTurnLocally();
        var endTurn = new EndPlayerTurnAction(player, previous);
        RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(endTurn); await endTurn.CompletionTask.WaitAsync(deadline.Token);
        while (player.PlayerCombatState is not { Phase: PlayerTurnPhase.Play } current || current.TurnNumber <= previous)
        { deadline.Token.ThrowIfCancellationRequested(); EnsureWithinDeadline(); await NextFrameAsync(); }
        string endedState = ContinuationStamp.CapturePredicted(player, ended.Simulator, ended.Turn, endRoot.Forecast, endRoot.StartTurnNumber).StateText;
        Equal(endedState, ContinuationStamp.CaptureLive(live).StateText, "native next turn full state/RNG");
        _completedChecks.Add("ClosedExhaust:FixedInkySlot:WithinTypeSequence:FourNativeActions:FutureShivsAndInky:FullStateHistoryRng:SixteenAttachedForks:NativeNextTurn:ParentLiveIsolation");
        _completedChecks.Add("TASK_CLOSED_EXHAUST " + JsonSerializer.Serialize(new { variant, checkpoints,
            initialNormalizedSha256 = Hash(Full(Canonical(parent))), endedNormalizedSha256 = Hash(State(Canonical(ended.Simulator))),
            root.CapturedRunModSubscriberCount, root.CapturedCombatModSubscriberCount, root.CapturedBaseLibCardModifiers,
            nativeEndSha256 = Hash(endedState), forkCount = children.Length, actualPrunes = 0, isWholeRootCertificate = false }));
    }
}

